// Comprehensive Lead Source ROI Analysis
const leads = $input.first().json;
const deals = $input.last().json;

// Group leads by source
const leadsBySource = {};
const dealsBySource = {};

// Process leads
if (Array.isArray(leads)) {
  leads.forEach(lead => {
    const source = lead['Lead Source'] || 'Unknown';
    if (!leadsBySource[source]) {
      leadsBySource[source] = {
        totalLeads: 0,
        qualifiedLeads: 0,
        hotLeads: 0,
        disqualifiedLeads: 0,
        avgScore: 0,
        totalScore: 0
      };
    }

    leadsBySource[source].totalLeads++;

    if (lead['Status'] === 'QUALIFIED' || lead['Status'] === 'HOT_LEAD') {
      leadsBySource[source].qualifiedLeads++;
    }
    if (lead['Status'] === 'HOT_LEAD') {
      leadsBySource[source].hotLeads++;
    }
    if (lead['Status'] === 'DISQUALIFIED') {
      leadsBySource[source].disqualifiedLeads++;
    }

    const score = parseFloat(lead['Qualification Score']) || 0;
    leadsBySource[source].totalScore += score;
  });
}

// Process deals
if (Array.isArray(deals)) {
  deals.forEach(deal => {
    const source = deal['Lead Source'] || 'Unknown';
    if (!dealsBySource[source]) {
      dealsBySource[source] = {
        totalDeals: 0,
        totalRevenue: 0,
        avgDealSize: 0
      };
    }

    dealsBySource[source].totalDeals++;
    const revenue = parseFloat(deal['Annual Premium']) || 0;
    dealsBySource[source].totalRevenue += revenue;
  });
}

// Calculate metrics per source
const sourceAnalysis = {};
const allSources = new Set([...Object.keys(leadsBySource), ...Object.keys(dealsBySource)]);

allSources.forEach(source => {
  const leadData = leadsBySource[source] || {
    totalLeads: 0,
    qualifiedLeads: 0,
    hotLeads: 0,
    disqualifiedLeads: 0,
    totalScore: 0
  };

  const dealData = dealsBySource[source] || {
    totalDeals: 0,
    totalRevenue: 0
  };

  const avgLeadScore = leadData.totalLeads > 0 ? leadData.totalScore / leadData.totalLeads : 0;
  const conversionRate = leadData.totalLeads > 0 ? (dealData.totalDeals / leadData.totalLeads) * 100 : 0;
  const avgDealSize = dealData.totalDeals > 0 ? dealData.totalRevenue / dealData.totalDeals : 0;
  const qualificationRate = leadData.totalLeads > 0 ? (leadData.qualifiedLeads / leadData.totalLeads) * 100 : 0;

  // Estimate cost per lead (you can customize these estimates)
  const costPerLeadEstimates = {
    'Facebook': 45,
    'Google': 60,
    'Referral': 0,
    'Organic': 0,
    'SmartFinancial': 55,
    'Aged Leads': 15,
    'Website': 30,
    'Chatbot': 25
  };

  const costPerLead = costPerLeadEstimates[source] || 40;
  const totalCost = leadData.totalLeads * costPerLead;
  const roi = totalCost > 0 ? ((dealData.totalRevenue - totalCost) / totalCost) * 100 : 0;
  const revenuePerLead = leadData.totalLeads > 0 ? dealData.totalRevenue / leadData.totalLeads : 0;

  sourceAnalysis[source] = {
    source: source,

    // Lead metrics
    totalLeads: leadData.totalLeads,
    qualifiedLeads: leadData.qualifiedLeads,
    hotLeads: leadData.hotLeads,
    disqualifiedLeads: leadData.disqualifiedLeads,
    avgLeadScore: Math.round(avgLeadScore),
    qualificationRate: Math.round(qualificationRate * 10) / 10,

    // Deal metrics
    totalDeals: dealData.totalDeals,
    totalRevenue: Math.round(dealData.totalRevenue),
    avgDealSize: Math.round(avgDealSize),
    conversionRate: Math.round(conversionRate * 10) / 10,

    // ROI metrics
    costPerLead: costPerLead,
    totalCost: totalCost,
    roi: Math.round(roi * 10) / 10,
    revenuePerLead: Math.round(revenuePerLead),

    // Quality grade
    grade: roi > 200 ? 'A+' : roi > 100 ? 'A' : roi > 50 ? 'B' : roi > 0 ? 'C' : 'D',

    // Recommendation
    recommendation: roi > 100 ? '🟢 SCALE UP - High ROI source' :
                     roi > 50 ? '🟡 MAINTAIN - Profitable source' :
                     roi > 0 ? '🟠 OPTIMIZE - Low ROI, needs improvement' :
                     '🔴 PAUSE - Unprofitable, consider stopping'
  };
});

// Sort by ROI
const sortedSources = Object.values(sourceAnalysis).sort((a, b) => b.roi - a.roi);

// Calculate totals
const totals = {
  totalLeads: sortedSources.reduce((sum, s) => sum + s.totalLeads, 0),
  totalDeals: sortedSources.reduce((sum, s) => sum + s.totalDeals, 0),
  totalRevenue: sortedSources.reduce((sum, s) => sum + s.totalRevenue, 0),
  totalCost: sortedSources.reduce((sum, s) => sum + s.totalCost, 0),
  avgConversionRate: 0,
  overallROI: 0
};

totals.avgConversionRate = totals.totalLeads > 0 ? (totals.totalDeals / totals.totalLeads) * 100 : 0;
totals.overallROI = totals.totalCost > 0 ? ((totals.totalRevenue - totals.totalCost) / totals.totalCost) * 100 : 0;

return {
  json: {
    reportDate: new Date().toISOString(),
    reportPeriod: 'Last 30 Days',
    totals: totals,
    sourceBreakdown: sortedSources,
    topPerformers: sortedSources.slice(0, 3),
    worstPerformers: sortedSources.slice(-3).reverse(),
    recommendations: sortedSources.map(s => ({
      source: s.source,
      recommendation: s.recommendation,
      roi: s.roi
    }))
  }
};

